#!/usr/bin/env bash
set -euo pipefail

cd /opt/laravel-deploy
# deployment.env is generated by CodeBuild and included in the CodePipeline artifact.
source deployment.env
IMAGE_URI="$(python3 -c 'import json; print(json.load(open("image-detail.json"))["imageUri"])')"
REGISTRY="${IMAGE_URI%%/*}"
REGION="$AWS_REGION"
COMPONENT="$APP_COMPONENT"

aws ecr get-login-password --region "$REGION" | docker login --username AWS --password-stdin "$REGISTRY"
docker pull "$IMAGE_URI"
docker rm -f "laravel-$COMPONENT" 2>/dev/null || true
docker run -d --name "laravel-$COMPONENT" --restart unless-stopped -p 80:80 \
  --env-file "/etc/laravel/$COMPONENT.env" \
  "$IMAGE_URI"
